import{_ as t,o as e,c as s,a5 as r}from"./chunks/framework.DJo0M80U.js";const c=JSON.parse('{"title":"原子写回","description":"“原子写回”指的是：当子组件需要把变更同步给父组件时，通过唯一且明确的一次写入动作把“完整的新值”提交回去，而不是在子组件里分散地、逐字段地、悄悄地修改原对象 。 换句话说—— 只走一条写回通道，一次性提交 ；不在多处“边读边改”。 为什么要这样做： 可追踪 ：父组件只需要监听一。","frontmatter":{"title":"原子写回","date":"2026-08-11T00:00:00.000Z","categories":["Vue 系统教程"],"tags":["Vue","Vue3","前端","教程","OneNote","响应式与组合式 API"],"description":"“原子写回”指的是：当子组件需要把变更同步给父组件时，通过唯一且明确的一次写入动作把“完整的新值”提交回去，而不是在子组件里分散地、逐字段地、悄悄地修改原对象 。 换句话说—— 只走一条写回通道，一次性提交 ；不在多处“边读边改”。 为什么要这样做： 可追踪 ：父组件只需要监听一。","sidebarWeight":136,"lastUpdated":false,"feed":false,"source":"onenote","sourceNote":"OneNote/f-vue/响应式问题/Prop.属性名传入composable失去响应/原子写回.md"},"headers":[],"relativePath":"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/原子写回.md","filePath":"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/原子写回.md"}'),n={name:"posts/Vue系统教程/03-响应式与组合式 API/Prop.属性名传入composable失去响应/原子写回.md"};function l(g,o,a,i,p,d){return e(),s("div",null,[...o[0]||(o[0]=[r('<div><h1 id="原子写回" tabindex="-1">原子写回 <a class="header-anchor" href="#原子写回" aria-label="Permalink to &quot;原子写回&quot;">​</a></h1><blockquote><p>本节目标：理解“原子写回”的核心思路，并能把它用于实际开发或面试表达。 <strong>“原子写回”指的是：当子组件需要把变更同步给父组件时，通过唯一且明确的一次写入动作把“完整的新值”提交回去，而不是在子组件里分散地、逐字段地、悄悄地修改原对象</strong>。 换句话说——<strong>只走一条写回通道，一次性提交</strong>；不在多处“边读边改”。 为什么要这样做：</p></blockquote><ul><li><strong>可追踪</strong>：父组件只需要监听一次“值被更新”的事件/模型写入，就能拿到<strong>变更后的整值</strong>，方便日志、校验、撤销/重做。</li><li><strong>一致性</strong>：避免“深层属性已被改，但父级并不知道”的脏改；也避免多次小改造成的中间不一致状态。</li><li><strong>性能与语义清晰</strong>：一次提交、一次渲染；变更语义更清楚（“我提交了一个新的 X”），而不是“我可能改了某些内层字段”。</li><li><strong>兼容响应式系统</strong>：Vue 更擅长捕获“引用变化”或“显式 set/emit”的信号；深改原对象常让依赖方<strong>无法正确感知</strong>或产生<strong>时序问题</strong>。</li></ul><p>对比两种思路（只讲原则，不给代码）：</p><ul><li>❌ <strong>深改</strong>：在子组件里直接改 props.modelValue.xxx = ...。这是<strong>隐式、多处、不可控</strong>的；父级很难集中感知。</li><li>✅ <strong>原子写回</strong>：在交互完成或阈值达成时，<strong>基于旧值拷贝/计算出一个“新值”</strong>，通过<strong>唯一的写回入口</strong>（如 v-model 的 setter / update:modelValue / defineModel 返回的 ref 赋值）<strong>一次性提交</strong>。</li></ul><p>应用场景举例（抽象表述）：</p><ul><li><strong>表单草稿</strong>：用户在子组件里编辑多个字段时，子组件内部先维护草稿；点击“保存”时，<strong>一次写回</strong>完整的表单对象。</li><li><strong>输入法/节流</strong>：输入过程在本地缓冲，结束/节流点到了再<strong>一次写回</strong>，避免把中间态频繁抛给父级。</li><li><strong>复杂派生</strong>：需要根据多个输入合成一个新值时，合成完成后<strong>一次写回</strong>，保证父级拿到的是<strong>成品</strong>而非半成品。</li></ul><p>一句话总结：<strong>原子写回 = 单一通道 + 一次提交完整新值</strong>。这样能让数据流清晰、可控、可回溯，并与 Vue 的响应式与 v-model/defineModel 设计天然对齐。</p></div>',1)])])}const _=t(n,[["render",l]]);export{c as __pageData,_ as default};
